CREATE OR REPLACE FUNCTION bloomscapes_demo.access_token_hook(event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare claims jsonb:=event->'claims';
begin
 if exists(select 1 from bloomscapes_demo.members where user_id=(event->>'user_id')::uuid and active) then
  claims:=jsonb_set(claims,'{role}','"bloomscapes_demo_client"'::jsonb);
  return jsonb_set(event,'{claims}',claims);
 end if;
 return event;
end $function$

CREATE OR REPLACE FUNCTION bloomscapes_demo.allocate(p_line uuid, p_quantity integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare l bloomscapes_demo.order_lines; batch_row record; take_qty int; remaining int:=p_quantity;
begin
 select * into strict l from bloomscapes_demo.order_lines where id=p_line;
 if p_quantity<=0 or bloomscapes_demo.variant_available(l.variant_id)<p_quantity then raise exception 'OUT_OF_STOCK: not enough qualified plants are available'; end if;
 for batch_row in select b.* from bloomscapes_demo.batches b join bloomscapes_demo.stock_groups g on g.id=b.group_id where g.variant_id=l.variant_id order by b.photo_at,b.id loop
  if not bloomscapes_demo.batch_eligible(batch_row.id) then continue; end if;
  take_qty:=least(remaining,bloomscapes_demo.group_available(batch_row.group_id),greatest(0,bloomscapes_demo.batch_match(batch_row.id)-bloomscapes_demo.batch_reserved(batch_row.id)));
  if take_qty>0 then
   insert into bloomscapes_demo.allocations(line_id,batch_id,reserved,evidence) values(p_line,batch_row.id,take_qty,
    jsonb_build_object('photo_path',batch_row.photo_path,'photo_version',batch_row.photo_version,'photo_at',batch_row.photo_at,'spec',batch_row.spec,'caliper',batch_row.caliper,'batch_revision',batch_row.revision));
   remaining:=remaining-take_qty;
  end if;
  exit when remaining=0;
 end loop;
 if remaining<>0 then raise exception 'OUT_OF_STOCK: availability changed'; end if;
end $function$

CREATE OR REPLACE FUNCTION bloomscapes_demo.assert_fulfillable(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a bloomscapes_demo.allocations; b bloomscapes_demo.batches;
begin
 select * into strict a from bloomscapes_demo.allocations where id=p_id;
 select * into strict b from bloomscapes_demo.batches where id=a.batch_id;
 if not bloomscapes_demo.batch_eligible(b.id) or bloomscapes_demo.batch_match(b.id)<bloomscapes_demo.batch_reserved(b.id)
 or bloomscapes_demo.group_open(b.group_id)<bloomscapes_demo.group_reserved(b.group_id)
 or b.spec is distinct from a.evidence->>'spec' or b.caliper is distinct from a.evidence->>'caliper'
 then raise exception 'FULFILLMENT_EXCEPTION: stock, seasonal limit, or advertised evidence requires review; release and replace undispatched stock if needed'; end if;
end $function$

CREATE OR REPLACE FUNCTION bloomscapes_demo.command(p_actor uuid, p_action text, p_payload jsonb, p_epoch integer, p_expected integer, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET lock_timeout TO '5s'
AS $function$
declare e bloomscapes_demo.environment; m bloomscapes_demo.members; prior bloomscapes_demo.commands; request_hash text;
 c bloomscapes_demo.carts; o bloomscapes_demo.orders; b bloomscapes_demo.batches; a bloomscapes_demo.allocations; t bloomscapes_demo.transfers; tl bloomscapes_demo.transfer_lines;
 l record; x jsonb; entity_id uuid; oid uuid; tid uuid; lid uuid; qty int; n int; used int; accepted_qty int; rejected_qty int; missing_qty int; remaining int; watermark bigint; source_seq bigint; response jsonb; changed boolean:=false;
begin
 -- The small demo serializes writes on its singleton environment row. This also
 -- makes Reset atomic with in-flight commands and background consumers.
 select * into e from bloomscapes_demo.environment where id='bloomscapes' for update;
 if e.project_ref<>'apztnscvagayslumnalr' then raise exception 'DEMO_ENVIRONMENT_REQUIRED'; end if;
 select * into m from bloomscapes_demo.members where user_id=p_actor and active;
 if not found then raise exception 'FORBIDDEN: active demo membership required'; end if;
 if p_action='state' then return bloomscapes_demo.read_state(p_actor); end if;
 if p_token is null or length(p_token)<16 or length(p_token)>128 then raise exception 'INVALID_REQUEST: request token required'; end if;
 if p_expected is null or p_expected<0 then raise exception 'INVALID_REQUEST: expected revision required'; end if;
 request_hash:=encode(extensions.digest(p_action||':'||coalesce(p_payload,'{}')::text||':'||p_expected::text,'sha256'),'hex');
 if p_epoch is distinct from e.epoch then
  if p_action='reset' and m.role='admin' then
   select * into prior from bloomscapes_demo.commands where epoch=p_epoch and actor_id=p_actor and token=p_token and action='reset';
   if found and prior.request_hash=request_hash and (prior.response->>'resulting_epoch')::int=e.epoch then return prior.response||jsonb_build_object('replayed',true); end if;
  end if;
  raise exception 'STALE_EPOCH: demo was reset; reload before retrying';
 end if;
 select * into prior from bloomscapes_demo.commands where epoch=e.epoch and actor_id=p_actor and token=p_token;
 if found then
  if prior.request_hash<>request_hash then raise exception 'IDEMPOTENCY_CONFLICT: token belongs to another request'; end if;
  return prior.response||jsonb_build_object('replayed',true);
 end if;
 if (select count(*) from bloomscapes_demo.commands where actor_id=p_actor and created_at>now()-interval '1 minute')>=180 then raise exception 'RATE_LIMITED: please wait before continuing'; end if;
 if p_action in('cart','checkout') and m.role not in('customer','admin') then raise exception 'FORBIDDEN: customer account required'; end if;
 if p_action in('inventory','import','accept','pick','prepare','dispatch','deliver_transfer','replace','photo_prepare','photo_finalize') and m.role not in('nursery','admin') then raise exception 'FORBIDDEN: nursery role required'; end if;
 if p_action in('receive','pack','ship','deliver_customer') and m.role not in('retailer','admin') then raise exception 'FORBIDDEN: retailer role required'; end if;
 if p_action in('reset','fail_sync','retry_sync','settings') and m.role<>'admin' then raise exception 'FORBIDDEN: administrator required'; end if;
 -- Shared cap rows and batch rows are locked in a single deterministic order.
 perform id from bloomscapes_demo.stock_groups order by id for update;
 perform id from bloomscapes_demo.batches order by id for update;

 if p_action='photo_prepare' then
  if p_expected<>e.revision then raise exception 'STALE_REVISION: refresh before uploading'; end if;
  if (select count(*) from bloomscapes_demo.photo_uploads)>=50 then raise exception 'DEMO_CAPACITY: demo photo upload limit reached (100 MB maximum); administrator retention review required'; end if;
  if coalesce(p_payload->>'sha256','') !~ '^[a-f0-9]{64}$' or coalesce(p_payload->>'ext','') not in('webp','png','jpg') or coalesce((p_payload->>'size')::int,0) not between 12 and 2000000 then raise exception 'INVALID_REQUEST: valid photo digest, format and size required'; end if;
  entity_id:=gen_random_uuid();
  insert into bloomscapes_demo.photo_uploads(id,epoch,actor_id,object_key,sha256,size) values(entity_id,e.epoch,p_actor,'e'||e.epoch||'/'||entity_id||'.'||(p_payload->>'ext'),p_payload->>'sha256',(p_payload->>'size')::int);
  response:=jsonb_build_object('ok',true,'upload_id',entity_id,'object_key','e'||e.epoch||'/'||entity_id||'.'||(p_payload->>'ext'));
 elsif p_action='photo_finalize' then
  if p_expected<>1 then raise exception 'STALE_REVISION: upload intent revision required'; end if;
  update bloomscapes_demo.photo_uploads set state='ready' where photo_uploads.id=(p_payload->>'upload_id')::uuid and epoch=e.epoch and actor_id=p_actor;
  if not found then raise exception 'NOT_FOUND: active upload intent required'; end if;
  response:=jsonb_build_object('ok',true);
 elsif p_action='cart' then
  select * into c from bloomscapes_demo.carts where owner_id=p_actor and state='open' for update;
  if not found then
   if p_expected<>0 then raise exception 'STALE_REVISION: refresh cart'; end if;
   insert into bloomscapes_demo.carts(owner_id,epoch) values(p_actor,e.epoch) returning * into c;
  elsif c.revision<>p_expected then raise exception 'STALE_REVISION: refresh cart'; end if;
  entity_id:=(p_payload->>'variant_id')::uuid; qty:=(p_payload->>'quantity')::int;
  if not exists(select 1 from bloomscapes_demo.variants where variants.id=entity_id) or qty is null or qty<0 or qty>500 then raise exception 'INVALID_REQUEST: valid plant and quantity required'; end if;
  if qty=0 then delete from bloomscapes_demo.cart_lines where cart_id=c.id and variant_id=entity_id;
  else insert into bloomscapes_demo.cart_lines(cart_id,variant_id,quantity) values(c.id,entity_id,qty) on conflict(cart_id,variant_id) do update set quantity=excluded.quantity; end if;
  update bloomscapes_demo.carts set revision=revision+1 where carts.id=c.id;
  response:=jsonb_build_object('ok',true,'cart_id',c.id);
 elsif p_action='checkout' then
  select * into c from bloomscapes_demo.carts where carts.id=(p_payload->>'cart_id')::uuid and owner_id=p_actor for update;
  if not found then raise exception 'NOT_FOUND: cart not found'; end if;
  if c.state='submitted' then select orders.id into oid from bloomscapes_demo.orders where cart_id=c.id; response:=jsonb_build_object('ok',true,'order_id',oid,'replayed',true);
  else
   if c.revision<>p_expected then raise exception 'STALE_REVISION: refresh cart'; end if;
   if not exists(select 1 from bloomscapes_demo.cart_lines where cart_id=c.id) then raise exception 'INVALID_REQUEST: cart is empty'; end if;
   if (select count(*) from bloomscapes_demo.orders)>=500 then raise exception 'DEMO_CAPACITY: reset demo before creating more orders'; end if;
   if coalesce(p_payload->>'customer','homeowner') not in('homeowner','landscaper') then raise exception 'INVALID_REQUEST: choose a synthetic customer'; end if;
   insert into bloomscapes_demo.orders(owner_id,cart_id,epoch,customer) values(p_actor,c.id,e.epoch,
    case when p_payload->>'customer'='landscaper' then '{"name":"Willow & Stone Landscape — DEMO","email":"orders@willow-stone.invalid","address":"200 Demo Garden Way, Sample City, ST 00000","type":"Landscaper"}'::jsonb
    else '{"name":"Avery Green — DEMO","email":"avery@example.invalid","address":"100 Demo Lane, Sample City, ST 00000","type":"Homeowner"}'::jsonb end) returning orders.id into oid;
   for l in select cl.*,v.price_cents from bloomscapes_demo.cart_lines cl join bloomscapes_demo.variants v on v.id=cl.variant_id where cart_id=c.id order by variant_id loop
    insert into bloomscapes_demo.order_lines(order_id,variant_id,quantity,unit_price_cents,advertised) values(oid,l.variant_id,l.quantity,l.price_cents,bloomscapes_demo.catalog_payload(l.variant_id)) returning order_lines.id into lid;
    perform bloomscapes_demo.allocate(lid,l.quantity);
   end loop;
   update bloomscapes_demo.orders set total_cents=(select sum(quantity*unit_price_cents) from bloomscapes_demo.order_lines where order_id=oid) where orders.id=oid;
   update bloomscapes_demo.carts set state='submitted',revision=revision+1 where carts.id=c.id;
   response:=jsonb_build_object('ok',true,'order_id',oid);
  end if;
 elsif p_action in('inventory','import') then
  select * into b from bloomscapes_demo.batches where batches.id=(p_payload->>'batch_id')::uuid;
  if not found then raise exception 'NOT_FOUND: inventory batch not found'; end if;
  if b.revision<>p_expected then raise exception 'STALE_REVISION: refresh inventory'; end if;
  if p_action='inventory' then
   if p_payload ? 'on_hand' then
    qty:=(p_payload->>'on_hand')::int; if qty<0 or qty>10000 then raise exception 'INVALID_REQUEST: on-hand quantity out of range'; end if;
    insert into bloomscapes_demo.movements(batch_id,quantity,kind,actor_id) values(b.id,qty-bloomscapes_demo.batch_on_hand(b.id),'count',p_actor);
   end if;
   if p_payload ? 'photo_path' and not ((p_payload->>'photo_path') ~ '^/plants/[a-z-]+\.webp$' or exists(select 1 from bloomscapes_demo.photo_uploads u where 'storage:'||u.object_key=p_payload->>'photo_path' and u.epoch=e.epoch and u.state='ready')) then raise exception 'INVALID_REQUEST: approved current-generation demo photo required'; end if;
   if p_payload ? 'hold_code' and p_payload->>'hold_code' not in('','H','S') then raise exception 'INVALID_REQUEST: unknown hold code'; end if;
   update bloomscapes_demo.batches set spec=case when p_payload ? 'spec' then left(p_payload->>'spec',300) else spec end,
    equivalence_approved=case when p_payload ? 'equivalence_approved' then (p_payload->>'equivalence_approved')::boolean when p_payload ? 'spec' and p_payload->>'spec' is distinct from spec then false else equivalence_approved end,
    published=coalesce((p_payload->>'published')::boolean,published),approved=coalesce((p_payload->>'approved')::boolean,approved),
    match_percent=coalesce((p_payload->>'match_percent')::numeric,match_percent),hold_code=coalesce(p_payload->>'hold_code',hold_code),
    photo_path=coalesce(p_payload->>'photo_path',photo_path),photo_at=case when p_payload ? 'photo_path' then now() when p_payload ? 'photo_at' and m.role='admin' then (p_payload->>'photo_at')::timestamptz else photo_at end,
    photo_version=case when p_payload ? 'photo_path' then gen_random_uuid() else photo_version end,
    initial_ptr=case when coalesce((p_payload->>'recapture')::boolean,false) then bloomscapes_demo.batch_ptr(b.id) else initial_ptr end,
    revision=revision+1,updated_at=now() where batches.id=b.id;
  else
   source_seq:=(p_payload->>'source_sequence')::bigint; watermark:=(p_payload->>'movement_watermark')::bigint; qty:=(p_payload->>'on_hand')::int; n:=(p_payload->>'open_limit')::int;
   if source_seq is null or source_seq<=b.source_sequence or source_seq<(select source_sequence from bloomscapes_demo.stock_groups where stock_groups.id=b.group_id) then raise exception 'STALE_IMPORT: source sequence must advance'; end if;
   if exists(select 1 from bloomscapes_demo.stock_groups g where g.id=b.group_id and g.source_sequence=source_seq and (g.baseline_open is distinct from n or g.movement_watermark is distinct from watermark)) then raise exception 'STALE_IMPORT: shared metadata conflicts with another row in this snapshot'; end if;
   if watermark is null or watermark<b.movement_watermark or watermark>(select coalesce(max(sequence),0) from bloomscapes_demo.movements) or watermark<(select movement_watermark from bloomscapes_demo.stock_groups where stock_groups.id=b.group_id) or (watermark<>0 and not exists(select 1 from bloomscapes_demo.movements where sequence=watermark)) then raise exception 'INVALID_WATERMARK: snapshot must identify incorporated movements'; end if;
   if qty is null or qty<0 or qty>10000 or n is null or n<0 or n>20000 then raise exception 'INVALID_REQUEST: import stock out of range'; end if;
   update bloomscapes_demo.batches set baseline_on_hand=qty,movement_watermark=watermark,source_sequence=source_seq,revision=revision+1,updated_at=now() where batches.id=b.id;
   update bloomscapes_demo.stock_groups set baseline_open=n,movement_watermark=watermark,source_sequence=source_seq where stock_groups.id=b.group_id;
   insert into bloomscapes_demo.imports(batch_id,source_sequence,movement_watermark,payload,actor_id) values(b.id,source_seq,watermark,p_payload,p_actor);
  end if;
  response:=jsonb_build_object('ok',true,'batch_id',b.id);
 elsif p_action in('reset','fail_sync','retry_sync','settings') then
  if p_expected<>e.revision then raise exception 'STALE_REVISION: refresh administrator controls'; end if;
  if p_action='reset' then
   if p_payload->>'confirmation' is distinct from 'RESET SYNTHETIC DEMO' then raise exception 'INVALID_REQUEST: reset confirmation required'; end if;
   perform bloomscapes_demo.seed_fixtures();
  elsif p_action='fail_sync' then update bloomscapes_demo.environment set fail_sync_remaining=1 where environment.id=e.id;
  elsif p_action='retry_sync' then update bloomscapes_demo.outbox set next_attempt_at=now() where state='failed';
  else
   if p_payload->>'season' not in('F1','S1') or (p_payload->>'sales_year')::int not between 20 and 40 then raise exception 'INVALID_REQUEST: valid demo season/year required'; end if;
   update bloomscapes_demo.environment set season=p_payload->>'season',sales_year=(p_payload->>'sales_year')::int where environment.id=e.id;
  end if;
  response:=jsonb_build_object('ok',true,'resulting_epoch',(select epoch from bloomscapes_demo.environment where environment.id=e.id));
 else
  oid:=(p_payload->>'order_id')::uuid;
  select * into o from bloomscapes_demo.orders where orders.id=oid for update;
  if not found then raise exception 'NOT_FOUND: order not found'; end if;
  if m.role='customer' and (o.owner_id<>p_actor or p_action<>'cancel') then raise exception 'FORBIDDEN: this order action is not available'; end if;
  if o.revision<>p_expected then raise exception 'STALE_REVISION: refresh order'; end if;
  if p_action='accept' then
   if o.accepted_at is not null or not exists(select 1 from bloomscapes_demo.order_lines where order_id=oid and cancelled<quantity) then raise exception 'INVALID_TRANSITION: order cannot be accepted'; end if;
   update bloomscapes_demo.orders set accepted_at=now() where orders.id=oid;
  elsif p_action='pick' then
   if o.accepted_at is null then raise exception 'INVALID_TRANSITION: accept the nursery order first'; end if;
   for x in select * from jsonb_array_elements(p_payload->'lines') loop
    select a1.* into a from bloomscapes_demo.allocations a1 join bloomscapes_demo.order_lines ol on ol.id=a1.line_id where a1.id=(x->>'allocation_id')::uuid and ol.order_id=oid;
    if not found then raise exception 'NOT_FOUND: allocation not found'; end if;
    qty:=(x->>'quantity')::int;
    if qty is null or qty<a.dispatched or qty>a.reserved-a.released then raise exception 'INVALID_QUANTITY: picked quantity must fit reservation'; end if;
    if qty>a.picked then perform bloomscapes_demo.assert_fulfillable(a.id); end if;
    if qty<a.picked then
     update bloomscapes_demo.transfers set status='cancelled' where order_id=oid and status='prepared' and exists(select 1 from bloomscapes_demo.transfer_lines q where q.transfer_id=transfers.id and q.allocation_id=a.id);
    end if;
    update bloomscapes_demo.allocations set picked=qty where allocations.id=a.id; changed:=true;
   end loop;
   if not changed then raise exception 'INVALID_REQUEST: pick quantities required'; end if;
  elsif p_action='prepare' then
   if o.accepted_at is null then raise exception 'INVALID_TRANSITION: nursery order not accepted'; end if;
   insert into bloomscapes_demo.transfers(order_id) values(oid) returning transfers.id into tid;
   for l in select a1.* from bloomscapes_demo.allocations a1 join bloomscapes_demo.order_lines ol on ol.id=a1.line_id where ol.order_id=oid order by a1.id loop
    qty:=l.picked-l.dispatched-coalesce((select sum(tl1.quantity)::int from bloomscapes_demo.transfer_lines tl1 join bloomscapes_demo.transfers t1 on t1.id=tl1.transfer_id where tl1.allocation_id=l.id and t1.status='prepared'),0);
    if qty>0 then insert into bloomscapes_demo.transfer_lines(transfer_id,allocation_id,quantity) values(tid,l.id,qty); changed:=true; end if;
   end loop;
   if not changed then raise exception 'INVALID_TRANSITION: no picked plants ready for transfer'; end if;
  elsif p_action in('dispatch','deliver_transfer','receive') then
   select * into t from bloomscapes_demo.transfers where transfers.id=(p_payload->>'transfer_id')::uuid and order_id=oid for update;
   if not found then raise exception 'NOT_FOUND: transfer not found'; end if;
   if p_action='dispatch' then
    if t.status<>'prepared' then raise exception 'INVALID_TRANSITION: transfer is not prepared'; end if;
    for tl in select * from bloomscapes_demo.transfer_lines where transfer_id=t.id order by allocation_id loop
     select * into a from bloomscapes_demo.allocations where allocations.id=tl.allocation_id;
     perform bloomscapes_demo.assert_fulfillable(a.id);
     insert into bloomscapes_demo.movements(batch_id,quantity,kind,transfer_line_id,actor_id) values(a.batch_id,-tl.quantity,'dispatch',tl.id,p_actor);
     update bloomscapes_demo.allocations set dispatched=dispatched+tl.quantity where allocations.id=a.id;
     update bloomscapes_demo.batches set revision=revision+1,updated_at=now() where batches.id=a.batch_id;
    end loop;
    update bloomscapes_demo.transfers set status='dispatched',dispatched_at=now() where transfers.id=t.id;
   elsif p_action='deliver_transfer' then
    if t.status<>'dispatched' then raise exception 'INVALID_TRANSITION: dispatch the transfer first'; end if;
    update bloomscapes_demo.transfers set status='delivered',delivered_at=now() where transfers.id=t.id;
   else
    if t.status<>'delivered' then raise exception 'INVALID_TRANSITION: nursery delivery confirmation required before receipt'; end if;
    for x in select * from jsonb_array_elements(p_payload->'lines') loop
     select * into tl from bloomscapes_demo.transfer_lines where transfer_lines.id=(x->>'transfer_line_id')::uuid and transfer_id=t.id;
     if not found then raise exception 'NOT_FOUND: transfer line not found'; end if;
     accepted_qty:=coalesce((x->>'accepted')::int,0); rejected_qty:=coalesce((x->>'rejected')::int,0); missing_qty:=coalesce((x->>'missing')::int,0);
     used:=coalesce((select sum(accepted+rejected+missing)::int from bloomscapes_demo.receipts where transfer_line_id=tl.id),0);
     if least(accepted_qty,rejected_qty,missing_qty)<0 or accepted_qty+rejected_qty+missing_qty=0 or used+accepted_qty+rejected_qty+missing_qty>tl.quantity then raise exception 'INVALID_QUANTITY: receipt exceeds outstanding transfer quantity'; end if;
     if rejected_qty+missing_qty>0 and length(trim(coalesce(x->>'reason','')))<3 then raise exception 'INVALID_REQUEST: a shortage or rejection reason is required'; end if;
     insert into bloomscapes_demo.receipts(transfer_line_id,accepted,rejected,missing,reason,actor_id) values(tl.id,accepted_qty,rejected_qty,missing_qty,left(coalesce(x->>'reason',''),300),p_actor); changed:=true;
    end loop;
    if not changed then raise exception 'INVALID_REQUEST: receipt quantities required'; end if;
    if not exists(select 1 from bloomscapes_demo.transfer_lines tl1 where tl1.transfer_id=t.id and tl1.quantity>coalesce((select sum(r.accepted+r.rejected+r.missing) from bloomscapes_demo.receipts r where r.transfer_line_id=tl1.id),0)) then update bloomscapes_demo.transfers set status='received' where transfers.id=t.id; end if;
   end if;
  elsif p_action in('pack','ship') then
   if p_action='ship' then insert into bloomscapes_demo.shipments(order_id,tracking) values(oid,'DEMO-'||upper(substr(gen_random_uuid()::text,1,8))) returning shipments.id into tid; end if;
   for x in select * from jsonb_array_elements(p_payload->'lines') loop
    select a1.* into a from bloomscapes_demo.allocations a1 join bloomscapes_demo.order_lines ol on ol.id=a1.line_id where a1.id=(x->>'allocation_id')::uuid and ol.order_id=oid;
    if not found then raise exception 'NOT_FOUND: allocation not found'; end if;
    qty:=(x->>'quantity')::int;
    if qty is null or qty<=0 then raise exception 'INVALID_QUANTITY: positive quantity required'; end if;
    if p_action='pack' then
     if a.packed+qty>bloomscapes_demo.accepted(a.id) then raise exception 'INVALID_QUANTITY: cannot pack more than accepted'; end if;
     update bloomscapes_demo.allocations set packed=packed+qty where allocations.id=a.id;
    else
     if a.shipped+qty>a.packed then raise exception 'INVALID_QUANTITY: cannot ship more than packed'; end if;
     insert into bloomscapes_demo.shipment_lines(shipment_id,allocation_id,quantity) values(tid,a.id,qty);
     update bloomscapes_demo.allocations set shipped=shipped+qty where allocations.id=a.id;
    end if;
    changed:=true;
   end loop;
   if not changed then raise exception 'INVALID_REQUEST: quantities required'; end if;
  elsif p_action='deliver_customer' then
   update bloomscapes_demo.shipments set delivered_at=now() where shipments.id=(p_payload->>'shipment_id')::uuid and order_id=oid and delivered_at is null;
   if not found then raise exception 'INVALID_TRANSITION: shipment is missing or already delivered'; end if;
  elsif p_action in('cancel','replace') then
   for l in select * from bloomscapes_demo.order_lines where order_id=oid and (not(p_payload ? 'line_id') or order_lines.id=(p_payload->>'line_id')::uuid) order by order_lines.id loop
    select coalesce(sum(a1.dispatched-bloomscapes_demo.failed_receipt(a1.id)),0)::int,coalesce(sum(a1.reserved-a1.released-a1.dispatched),0)::int into used,n from bloomscapes_demo.allocations a1 where line_id=l.id;
    remaining:=l.quantity-l.cancelled-used;
    if p_action='cancel' then
     if remaining<=0 then continue; end if;
     update bloomscapes_demo.transfers set status='cancelled' where order_id=oid and status='prepared' and exists(select 1 from bloomscapes_demo.transfer_lines tl1 join bloomscapes_demo.allocations a1 on a1.id=tl1.allocation_id where tl1.transfer_id=transfers.id and a1.line_id=l.id);
     update bloomscapes_demo.allocations set picked=dispatched,released=reserved-dispatched where line_id=l.id;
     update bloomscapes_demo.order_lines set cancelled=cancelled+remaining where order_lines.id=l.id; changed:=true;
    else
     -- Explicit replacement can release any undispatched plants, including
     -- picked plants whose evidence expired. In-transit units are never released.
     if coalesce((p_payload->>'release_unpicked')::boolean,false) then
      update bloomscapes_demo.transfers set status='cancelled' where order_id=oid and status='prepared' and exists(select 1 from bloomscapes_demo.transfer_lines q join bloomscapes_demo.allocations z on z.id=q.allocation_id where q.transfer_id=transfers.id and z.line_id=l.id);
      update bloomscapes_demo.allocations set picked=dispatched,released=reserved-dispatched where line_id=l.id;
      select coalesce(sum(reserved-released-dispatched),0)::int into n from bloomscapes_demo.allocations where line_id=l.id;
     end if;
     qty:=remaining-n;
     if qty>0 then perform bloomscapes_demo.allocate(l.id,qty); changed:=true; end if;
    end if;
   end loop;
   if not changed then raise exception 'INVALID_TRANSITION: no eligible unfulfilled remainder'; end if;
  else raise exception 'INVALID_ACTION: unsupported demo operation'; end if;
  update bloomscapes_demo.orders set revision=revision+1 where orders.id=oid;
  response:=jsonb_build_object('ok',true,'order_id',oid,'transfer_id',case when p_action='prepare' then tid else null end,'shipment_id',case when p_action='ship' then tid else null end);
 end if;
 update bloomscapes_demo.environment set revision=revision+1,updated_at=now() where environment.id=e.id;
 insert into bloomscapes_demo.audit(epoch,actor_id,action,order_id,payload) values(e.epoch,p_actor,p_action,oid,p_payload);
 perform bloomscapes_demo.tick();
 insert into bloomscapes_demo.commands(epoch,actor_id,token,action,request_hash,response) values(e.epoch,p_actor,p_token,p_action,request_hash,response);
 return response;
end $function$

CREATE OR REPLACE FUNCTION bloomscapes_demo.enqueue_catalog()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare e bloomscapes_demo.environment; v record; payload jsonb;
begin
 select * into e from bloomscapes_demo.environment where id='bloomscapes' for update;
 for v in select id from bloomscapes_demo.variants order by id loop
  payload:=bloomscapes_demo.catalog_payload(v.id);
  if payload is distinct from (select o.payload from bloomscapes_demo.outbox o where o.variant_id=v.id and o.epoch=e.epoch order by o.revision desc limit 1) then
   update bloomscapes_demo.environment set revision=revision+1 where id=e.id returning revision into e.revision;
   insert into bloomscapes_demo.outbox(variant_id,epoch,revision,payload) values(v.id,e.epoch,e.revision,payload);
  end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION bloomscapes_demo.process_outbox()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare e bloomscapes_demo.environment; r bloomscapes_demo.outbox; n int:=0;
begin
 select * into e from bloomscapes_demo.environment where id='bloomscapes' for update;
 if e.project_ref<>'apztnscvagayslumnalr' then raise exception 'DEMO_ENVIRONMENT_REQUIRED'; end if;
 for r in select * from bloomscapes_demo.outbox where state in('pending','failed') and next_attempt_at<=now() order by id limit 30 for update loop
  if r.epoch<>e.epoch then update bloomscapes_demo.outbox set state='superseded' where id=r.id; continue; end if;
  if e.fail_sync_remaining>0 then
   e.fail_sync_remaining:=e.fail_sync_remaining-1;
   update bloomscapes_demo.environment set fail_sync_remaining=e.fail_sync_remaining where id=e.id;
   update bloomscapes_demo.outbox set state='failed',attempts=attempts+1,error='Simulated partner delivery failure',next_attempt_at=now()+interval '60 seconds' where id=r.id;
  else
   perform bloomscapes_demo.apply_partner_snapshot(r);
   update bloomscapes_demo.outbox set state='applied',attempts=attempts+1,error=null where id=r.id;
   update bloomscapes_demo.environment set last_sync_at=now() where id=e.id;
   n:=n+1;
  end if;
 end loop;
 return n;
end $function$

CREATE OR REPLACE FUNCTION bloomscapes_demo.seed_fixtures()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare f jsonb; p jsonb; b jsonb; vid uuid; gid uuid; e bloomscapes_demo.environment;
begin
 select * into e from bloomscapes_demo.environment where id='bloomscapes' for update;
 if e.project_ref<>'apztnscvagayslumnalr' then raise exception 'DEMO_ENVIRONMENT_REQUIRED'; end if;
 select payload into f from bloomscapes_demo.fixture_catalog where id=true;
 if f is null then raise exception 'FIXTURES_REQUIRED'; end if;
 -- Exact private schema targets only; preserve accounts, access grants, and reset audit.
 delete from bloomscapes_demo.shipment_lines where shipment_id is not null; delete from bloomscapes_demo.shipments where id is not null;
 delete from bloomscapes_demo.receipts where id is not null; delete from bloomscapes_demo.movements where sequence is not null; delete from bloomscapes_demo.imports where id is not null;
 delete from bloomscapes_demo.transfer_lines where id is not null; delete from bloomscapes_demo.transfers where id is not null;
 delete from bloomscapes_demo.allocations where id is not null; delete from bloomscapes_demo.order_lines where id is not null; delete from bloomscapes_demo.orders where epoch<=e.epoch;
 delete from bloomscapes_demo.cart_lines where cart_id is not null; delete from bloomscapes_demo.carts where epoch<=e.epoch;
 delete from bloomscapes_demo.catalog where epoch<=e.epoch; delete from bloomscapes_demo.outbox where epoch<=e.epoch;
 delete from bloomscapes_demo.batches where id is not null; delete from bloomscapes_demo.stock_groups where id is not null; delete from bloomscapes_demo.variants where id is not null;
 update bloomscapes_demo.environment set epoch=epoch+1,revision=revision+1,season='F1',sales_year=27,fail_sync_remaining=0,last_sync_at=null,updated_at=now() where id=e.id;
 for p in select * from jsonb_array_elements(f) loop
  insert into bloomscapes_demo.variants(slug,sku,name,botanical,category,container,description,price_cents,photo_path)
   values(p->>'slug',p->>'sku',p->>'name',p->>'botanical',p->>'category',p->>'container',p->>'description',(p->>'price_cents')::int,p->>'photo_path') returning id into vid;
  insert into bloomscapes_demo.stock_groups(variant_id,season,sales_year,baseline_open) values(vid,coalesce(p->>'season','F1'),coalesce((p->>'sales_year')::int,27),(p->>'open_limit')::int) returning id into gid;
  for b in select * from jsonb_array_elements(p->'batches') loop
   insert into bloomscapes_demo.batches(group_id,source_id,location,lot,label,baseline_on_hand,external_committed,other_partner,hold_quantity,hold_code,initial_ptr,match_percent,spec,caliper,photo_path,photo_at)
   values(gid,p->>'sku'||':'||(b->>'label'),b->>'location',coalesce(p->>'sales_year','27')||'.'||coalesce(p->>'season','F1'),b->>'label',(b->>'on_hand')::int,
    coalesce((b->>'external_committed')::int,0),coalesce((b->>'other_partner')::int,0),coalesce((b->>'hold_quantity')::int,0),coalesce(b->>'hold_code',''),
    greatest(0,(b->>'on_hand')::int-coalesce((b->>'external_committed')::int,0)-coalesce((b->>'other_partner')::int,0)-coalesce((b->>'hold_quantity')::int,0)),
    coalesce((b->>'match_percent')::numeric,100),b->>'spec',coalesce(b->>'caliper',''),coalesce(b->>'photo_path',p->>'photo_path'),now()-interval '1 day');
  end loop;
 end loop;
 perform bloomscapes_demo.tick();
end $function$

CREATE OR REPLACE FUNCTION bloomscapes_demo.tick()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 perform bloomscapes_demo.enqueue_catalog();
 perform bloomscapes_demo.process_outbox();
 delete from bloomscapes_demo.outbox where state in('applied','superseded') and created_at<now()-interval '7 days';
end $function$

CREATE OR REPLACE FUNCTION private.require_codex_ops_dylan_v1()
 RETURNS public.profiles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  profile public.profiles%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'CODEX_OPS_AUTH_REQUIRED';
  end if;
  select p.* into profile
  from public.profiles p
  where p.id = auth.uid()
    and lower(btrim(p.username)) = 'dylan_collyge'
    and p.disabled_at is null
    and (p.locked_until is null or p.locked_until <= now());
  if profile.id is null then
    raise exception using errcode = '42501', message = 'CODEX_OPS_DYLAN_ONLY';
  end if;
  return profile;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_codex_ops_message_v1(p_task_id uuid, p_expected_revision integer, p_body text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  profile public.profiles%rowtype;
  task private.codex_ops_tasks%rowtype;
  message private.codex_ops_messages%rowtype;
  clean_body text := btrim(coalesce(p_body, ''));
begin
  profile := private.require_codex_ops_dylan_v1();
  if not private.codex_ops_flag_enabled_v1('codex_ops_enabled') then
    raise exception using errcode = '42501', message = 'CODEX_OPS_SUBMISSION_DISABLED';
  end if;
  if char_length(clean_body) not between 1 and 12000 then
    raise exception using errcode = '22023', message = 'CODEX_OPS_MESSAGE_INVALID';
  end if;
  select * into task from private.codex_ops_tasks t where t.id = p_task_id and t.created_by = profile.id for update;
  if task.id is null then raise exception using errcode = 'P0002', message = 'CODEX_OPS_TASK_NOT_FOUND'; end if;
  select * into message from private.codex_ops_messages m
  where m.task_id = task.id and m.client_idempotency_key = p_idempotency_key;
  if message.id is not null then
    return jsonb_build_object('id', message.id, 'taskId', task.id, 'revision', task.revision, 'recovered', true);
  end if;
  if task.revision <> p_expected_revision then
    raise exception using errcode = '40001', message = 'CODEX_OPS_REVISION_CONFLICT';
  end if;
  if task.status in ('diagnosing', 'fixing', 'testing', 'deploying', 'live', 'reverted', 'cancelled') then
    raise exception using errcode = '55000', message = 'CODEX_OPS_TASK_BUSY_OR_TERMINAL';
  end if;
  insert into private.codex_ops_messages (task_id, actor_type, actor_username, body, client_idempotency_key)
  values (task.id, 'user', 'dylan_collyge', clean_body, p_idempotency_key)
  returning * into message;
  update private.codex_ops_tasks
  set revision = revision + 1,
      status = case when status in ('needs_input', 'blocked', 'failed', 'needs_escalation', 'ready_for_approval') then 'queued' else status end,
      approved_sha = null,
      branch_name = case when status = 'ready_for_approval' then null else branch_name end,
      pull_request_number = case when status = 'ready_for_approval' then null else pull_request_number end,
      pull_request_url = case when status = 'ready_for_approval' then null else pull_request_url end,
      head_sha = case when status = 'ready_for_approval' then null else head_sha end,
      path_policy_passed = case when status = 'ready_for_approval' then false else path_policy_passed end,
      required_checks_passed = case when status = 'ready_for_approval' then false else required_checks_passed end,
      terminal_at = null,
      updated_at = now()
  where id = task.id returning * into task;
  insert into private.codex_ops_events (task_id, revision, event_type, sanitized_payload)
  values (task.id, task.revision, 'message.added', '{}'::jsonb);
  return jsonb_build_object('id', message.id, 'taskId', task.id, 'revision', task.revision, 'recovered', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_codex_ops_repair_result_service_v2(p_task_id uuid, p_expected_revision integer, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  task private.codex_ops_tasks%rowtype;
  changed text[];
  message_body text;
  recent_repair_attempts integer;
begin
  select * into task
  from private.codex_ops_tasks t
  where t.id = p_task_id
  for update;
  if task.id is null then
    raise exception using errcode = 'P0002', message = 'CODEX_OPS_TASK_NOT_FOUND';
  end if;
  if task.revision <> p_expected_revision then
    raise exception using errcode = '40001', message = 'CODEX_OPS_REVISION_CONFLICT';
  end if;
  if task.status <> 'fixing' then
    raise exception using errcode = '55000', message = 'CODEX_OPS_REPAIR_NOT_ALLOWED';
  end if;
  if octet_length(coalesce(p_payload, '{}'::jsonb)::text) > 131072 then
    raise exception using errcode = '22023', message = 'CODEX_OPS_PAYLOAD_TOO_LARGE';
  end if;
  if task.repair_attempts >= 2 then
    raise exception using errcode = '54000', message = 'CODEX_OPS_REPAIR_LIMIT';
  end if;
  if task.incident_fingerprint is not null then
    select coalesce(sum(t.repair_attempts), 0)::integer
    into recent_repair_attempts
    from private.codex_ops_tasks t
    where t.incident_fingerprint = task.incident_fingerprint
      and t.updated_at >= now() - interval '60 minutes';
    if recent_repair_attempts >= 2 then
      raise exception using errcode = '54000', message = 'CODEX_OPS_FINGERPRINT_REPAIR_LIMIT';
    end if;
  end if;

  changed := coalesce(
    array(select jsonb_array_elements_text(coalesce(p_payload->'changedFiles', '[]'::jsonb))),
    '{}'::text[]
  );
  message_body := left(btrim(coalesce(p_payload->>'summary', 'Repair prepared.')), 12000);
  if coalesce((p_payload->>'escalationRequired')::boolean, false)
     or p_payload->>'risk' in ('high', 'complex') then
    update private.codex_ops_tasks set
      status = 'needs_escalation',
      repair_attempts = repair_attempts + 1,
      risk_level = case
        when p_payload->>'risk' in ('high', 'complex') then p_payload->>'risk'
        else risk_level
      end,
      sanitized_repair_summary = p_payload,
      changed_files = '{}'::text[],
      updated_at = now()
    where id = task.id
    returning * into task;
  else
    update private.codex_ops_tasks set
      status = 'testing',
      repair_attempts = repair_attempts + 1,
      sanitized_repair_summary = p_payload,
      changed_files = changed,
      updated_at = now()
    where id = task.id
    returning * into task;
  end if;

  insert into private.codex_ops_messages
    (task_id, actor_type, actor_username, model, body)
  values
    (task.id, 'agent', 'terra', 'gpt-5.6-terra', message_body);
  insert into private.codex_ops_events
    (task_id, revision, event_type, sanitized_payload)
  values
    (task.id, task.revision, 'repair.result', jsonb_build_object('status', task.status));
  insert into private.codex_ops_audit_events
    (task_id, actor_type, actor_key, action, outcome)
  values
    (task.id, 'runner', 'github-oidc', 'repair.result', 'succeeded');

  return jsonb_build_object(
    'taskId', task.id,
    'revision', task.revision,
    'status', task.status,
    'headSha', task.head_sha
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_codex_ops_service_event_v1(p_task_id uuid, p_expected_revision integer, p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  task private.codex_ops_tasks%rowtype;
  attachment_id uuid;
  media_kind text;
  message_body text;
  next_status text;
  changed text[];
  new_revision integer;
  image_count integer;
  video_count integer;
  recent_repair_attempts integer;
begin
  select * into task from private.codex_ops_tasks t where t.id = p_task_id for update;
  if task.id is null then raise exception using errcode = 'P0002', message = 'CODEX_OPS_TASK_NOT_FOUND'; end if;
  if task.revision <> p_expected_revision then raise exception using errcode = '40001', message = 'CODEX_OPS_REVISION_CONFLICT'; end if;
  if octet_length(coalesce(p_payload, '{}'::jsonb)::text) > 131072 then
    raise exception using errcode = '22023', message = 'CODEX_OPS_PAYLOAD_TOO_LARGE';
  end if;

  if p_action = 'attachment.register' then
    attachment_id := coalesce(nullif(p_payload->>'id', '')::uuid, gen_random_uuid());
    media_kind := lower(coalesce(p_payload->>'mediaKind', ''));
    if media_kind not in ('image', 'video') then raise exception using errcode = '22023', message = 'CODEX_OPS_MEDIA_INVALID'; end if;
    select count(*) filter (where a.media_kind = 'image'), count(*) filter (where a.media_kind = 'video')
    into image_count, video_count
    from private.codex_ops_attachments a where a.task_id = task.id and a.status <> 'deleted';
    if (media_kind = 'image' and image_count >= 10) or (media_kind = 'video' and video_count >= 2) then
      raise exception using errcode = '22023', message = 'CODEX_OPS_ATTACHMENT_LIMIT';
    end if;
    insert into private.codex_ops_attachments (
      id, task_id, uploaded_by, client_idempotency_key, media_kind,
      original_name, declared_mime, object_path
    ) values (
      attachment_id, task.id, task.created_by,
      (p_payload->>'idempotencyKey')::uuid, media_kind,
      left(coalesce(p_payload->>'name', 'evidence'), 240),
      left(coalesce(p_payload->>'declaredMime', 'application/octet-stream'), 120),
      p_payload->>'objectPath'
    ) on conflict (task_id, client_idempotency_key) do nothing;
    return jsonb_build_object('taskId', task.id, 'revision', task.revision, 'attachmentId', attachment_id);

  elsif p_action in ('attachment.verify', 'attachment.reject', 'attachment.delete') then
    attachment_id := (p_payload->>'attachmentId')::uuid;
    update private.codex_ops_attachments a set
      status = case p_action when 'attachment.verify' then 'verified' when 'attachment.reject' then 'rejected' else 'deleted' end,
      detected_mime = case when p_action = 'attachment.verify' then p_payload->>'detectedMime' else a.detected_mime end,
      size_bytes = case when p_action = 'attachment.verify' then (p_payload->>'sizeBytes')::bigint else a.size_bytes end,
      object_etag = case when p_action = 'attachment.verify' then left(coalesce(p_payload->>'etag', ''), 240) else a.object_etag end,
      rejection_code = case when p_action = 'attachment.reject' then left(coalesce(p_payload->>'rejectionCode', 'SIGNATURE_MISMATCH'), 120) else a.rejection_code end,
      verified_at = case when p_action = 'attachment.verify' then now() else a.verified_at end,
      deleted_at = case when p_action = 'attachment.delete' then now() else a.deleted_at end
    where a.id = attachment_id and a.task_id = task.id;
    if not found then raise exception using errcode = 'P0002', message = 'CODEX_OPS_ATTACHMENT_NOT_FOUND'; end if;
    return jsonb_build_object('taskId', task.id, 'revision', task.revision, 'attachmentId', attachment_id, 'action', p_action);

  elsif p_action = 'dispatch.queue' then
    if exists (select 1 from private.codex_ops_attachments a where a.task_id = task.id and a.status = 'pending') then
      raise exception using errcode = '55000', message = 'CODEX_OPS_ATTACHMENTS_PENDING';
    end if;
    insert into private.codex_ops_dispatches (
      task_id, task_revision, action, client_idempotency_key
    ) values (
      task.id, task.revision, p_payload->>'dispatchAction', (p_payload->>'idempotencyKey')::uuid
    ) on conflict (task_id, client_idempotency_key) do nothing;
    insert into private.codex_ops_events (task_id, revision, event_type, sanitized_payload)
    values (task.id, task.revision, 'dispatch.queued', jsonb_build_object('action', p_payload->>'dispatchAction'));
    return jsonb_build_object('taskId', task.id, 'revision', task.revision, 'status', task.status);

  elsif p_action = 'runner.claim' then
    if task.status = 'diagnosing' then
      return jsonb_build_object('taskId', task.id, 'revision', task.revision, 'status', task.status, 'recovered', true);
    end if;
    if task.status <> 'queued' then raise exception using errcode = '55000', message = 'CODEX_OPS_TASK_NOT_QUEUED'; end if;
    next_status := case when p_payload->>'dispatchAction' = 'sol_review' then 'diagnosing' else 'diagnosing' end;
    update private.codex_ops_tasks set status = next_status, updated_at = now() where id = task.id returning * into task;

  elsif p_action = 'diagnosis.result' then
    message_body := left(btrim(coalesce(p_payload->>'summary', 'Diagnosis completed.')), 12000);
    next_status := case
      when coalesce((p_payload->>'needsInput')::boolean, false) then 'needs_input'
      when coalesce((p_payload->>'escalationRequired')::boolean, false) then 'needs_escalation'
      when not coalesce((p_payload->>'reproduced')::boolean, false) then 'blocked'
      when not coalesce((p_payload->>'repairAllowed')::boolean, false) then 'needs_escalation'
      else 'fixing'
    end;
    update private.codex_ops_tasks set
      status = next_status,
      incident_fingerprint = left(nullif(p_payload->>'fingerprint', ''), 240),
      risk_level = case when p_payload->>'risk' in ('low', 'medium', 'high', 'complex') then p_payload->>'risk' else 'medium' end,
      sanitized_diagnosis = p_payload,
      updated_at = now(),
      terminal_at = case when next_status = 'blocked' then now() else null end
    where id = task.id returning * into task;
    insert into private.codex_ops_messages (task_id, actor_type, actor_username, model, body)
    values (task.id, 'agent', 'luna', 'gpt-5.6-luna', message_body);

  elsif p_action = 'repair.result' then
    if task.status <> 'fixing' then raise exception using errcode = '55000', message = 'CODEX_OPS_REPAIR_NOT_ALLOWED'; end if;
    if task.repair_attempts >= 2 then raise exception using errcode = '54000', message = 'CODEX_OPS_REPAIR_LIMIT'; end if;
    if task.incident_fingerprint is not null then
      select coalesce(sum(t.repair_attempts), 0)::integer
      into recent_repair_attempts
      from private.codex_ops_tasks t
      where t.incident_fingerprint = task.incident_fingerprint
        and t.updated_at >= now() - interval '60 minutes';
      if recent_repair_attempts >= 2 then
        raise exception using errcode = '54000', message = 'CODEX_OPS_FINGERPRINT_REPAIR_LIMIT';
      end if;
    end if;
    changed := coalesce(array(select jsonb_array_elements_text(coalesce(p_payload->'changedFiles', '[]'::jsonb))), '{}'::text[]);
    message_body := left(btrim(coalesce(p_payload->>'summary', 'Repair prepared.')), 12000);
    update private.codex_ops_tasks set
      status = 'testing', repair_attempts = repair_attempts + 1,
      sanitized_repair_summary = p_payload,
      changed_files = changed,
      updated_at = now()
    where id = task.id returning * into task;
    insert into private.codex_ops_messages (task_id, actor_type, actor_username, model, body)
    values (task.id, 'agent', 'terra', 'gpt-5.6-terra', message_body);

  elsif p_action = 'publish.result' then
    if not coalesce((p_payload->>'pathPolicyPassed')::boolean, false) then
      next_status := 'blocked';
    elsif not coalesce((p_payload->>'requiredChecksPassed')::boolean, false) then
      next_status := 'failed';
    else
      next_status := 'ready_for_approval';
    end if;
    new_revision := task.revision + 1;
    update private.codex_ops_tasks set
      revision = new_revision,
      status = next_status,
      branch_name = left(nullif(p_payload->>'branch', ''), 240),
      pull_request_number = nullif(p_payload->>'pullRequestNumber', '')::bigint,
      pull_request_url = left(nullif(p_payload->>'pullRequestUrl', ''), 1000),
      head_sha = lower(nullif(p_payload->>'headSha', '')),
      approved_sha = null,
      path_policy_passed = coalesce((p_payload->>'pathPolicyPassed')::boolean, false),
      required_checks_passed = coalesce((p_payload->>'requiredChecksPassed')::boolean, false),
      test_summary = coalesce(p_payload->'tests', '[]'::jsonb),
      last_error_code = nullif(p_payload->>'errorCode', ''),
      updated_at = now(),
      terminal_at = case when next_status in ('blocked', 'failed') then now() else null end
    where id = task.id returning * into task;

  elsif p_action = 'deployment.merged' then
    if task.status <> 'deploying' or task.approved_sha is null then
      raise exception using errcode = '55000', message = 'CODEX_OPS_DEPLOYMENT_NOT_APPROVED';
    end if;
    update private.codex_ops_tasks set
      merged_sha = lower(nullif(p_payload->>'mergedSha', '')),
      updated_at = now()
    where id = task.id returning * into task;

  elsif p_action in ('deployment.live', 'deployment.failed', 'deployment.reverted') then
    next_status := case p_action when 'deployment.live' then 'live' when 'deployment.reverted' then 'reverted' else 'failed' end;
    update private.codex_ops_tasks set
      status = next_status,
      merged_sha = case when p_action = 'deployment.live' then lower(nullif(p_payload->>'mergedSha', '')) else merged_sha end,
      last_error_code = nullif(p_payload->>'errorCode', ''),
      updated_at = now(), terminal_at = now()
    where id = task.id returning * into task;
    update private.codex_ops_attachments set expires_at = now() + interval '30 days'
    where task_id = task.id and status = 'verified' and expires_at is null;
  else
    raise exception using errcode = '22023', message = 'CODEX_OPS_SERVICE_ACTION_INVALID';
  end if;

  insert into private.codex_ops_events (task_id, revision, event_type, sanitized_payload)
  values (task.id, task.revision, p_action, jsonb_build_object('status', task.status));
  insert into private.codex_ops_audit_events (task_id, actor_type, actor_key, action, outcome)
  values (task.id, 'runner', 'github-oidc', p_action, 'succeeded');
  return jsonb_build_object('taskId', task.id, 'revision', task.revision, 'status', task.status, 'headSha', task.head_sha);
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_codex_ops_deployment_v1(p_task_id uuid, p_expected_revision integer, p_head_sha text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  profile public.profiles%rowtype;
  task private.codex_ops_tasks%rowtype;
  approval private.codex_ops_approvals%rowtype;
  normalized_sha text := lower(btrim(coalesce(p_head_sha, '')));
begin
  profile := private.require_codex_ops_dylan_v1();
  if not private.codex_ops_flag_enabled_v1('codex_ops_deploy_enabled') then
    raise exception using errcode = '42501', message = 'CODEX_OPS_DEPLOYMENT_DISABLED';
  end if;
  if normalized_sha !~ '^[0-9a-f]{40}$' then raise exception using errcode = '22023', message = 'CODEX_OPS_SHA_INVALID'; end if;
  select * into task from private.codex_ops_tasks t where t.id = p_task_id and t.created_by = profile.id for update;
  if task.id is null then raise exception using errcode = 'P0002', message = 'CODEX_OPS_TASK_NOT_FOUND'; end if;
  select * into approval from private.codex_ops_approvals a
  where a.approved_by = profile.id and a.client_idempotency_key = p_idempotency_key;
  if approval.id is not null then
    return jsonb_build_object('approvalId', approval.id, 'taskId', task.id, 'revision', approval.task_revision, 'headSha', approval.head_sha, 'recovered', true);
  end if;
  if task.revision <> p_expected_revision then raise exception using errcode = '40001', message = 'CODEX_OPS_REVISION_CONFLICT'; end if;
  if task.status <> 'ready_for_approval' then raise exception using errcode = '55000', message = 'CODEX_OPS_NOT_READY'; end if;
  if task.head_sha is distinct from normalized_sha then raise exception using errcode = '40001', message = 'CODEX_OPS_HEAD_CHANGED'; end if;
  if not task.path_policy_passed or not task.required_checks_passed then raise exception using errcode = '55000', message = 'CODEX_OPS_CHECKS_INCOMPLETE'; end if;
  insert into private.codex_ops_approvals (
    task_id, task_revision, head_sha, approved_by, approved_by_username, client_idempotency_key
  ) values (task.id, task.revision, normalized_sha, profile.id, 'dylan_collyge', p_idempotency_key)
  returning * into approval;
  update private.codex_ops_tasks set approved_sha = normalized_sha, status = 'deploying', updated_at = now()
  where id = task.id;
  insert into private.codex_ops_events (task_id, revision, event_type, sanitized_payload)
  values (task.id, task.revision, 'deployment.approved', jsonb_build_object('headSha', normalized_sha));
  insert into private.codex_ops_audit_events (task_id, actor_type, actor_key, action, outcome, sanitized_metadata)
  values (task.id, 'user', 'dylan_collyge', 'deployment.approve', 'succeeded', jsonb_build_object('revision', task.revision, 'headSha', normalized_sha));
  return jsonb_build_object('approvalId', approval.id, 'taskId', task.id, 'revision', approval.task_revision, 'headSha', approval.head_sha, 'recovered', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_codex_ops_task_v1(p_task_id uuid, p_expected_revision integer, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  profile public.profiles%rowtype;
  task private.codex_ops_tasks%rowtype;
begin
  profile := private.require_codex_ops_dylan_v1();
  select * into task from private.codex_ops_tasks t where t.id = p_task_id and t.created_by = profile.id for update;
  if task.id is null then raise exception using errcode = 'P0002', message = 'CODEX_OPS_TASK_NOT_FOUND'; end if;
  if task.status = 'cancelled' then return jsonb_build_object('id', task.id, 'status', task.status, 'revision', task.revision); end if;
  if task.revision <> p_expected_revision then raise exception using errcode = '40001', message = 'CODEX_OPS_REVISION_CONFLICT'; end if;
  if task.status in ('deploying', 'live', 'reverted') then raise exception using errcode = '55000', message = 'CODEX_OPS_TASK_TERMINAL'; end if;
  update private.codex_ops_tasks set
    status = 'cancelled', revision = revision + 1, approved_sha = null,
    updated_at = now(), terminal_at = now()
  where id = task.id returning * into task;
  update private.codex_ops_attachments set expires_at = now() + interval '30 days'
  where task_id = task.id and status = 'verified' and expires_at is null;
  insert into private.codex_ops_events (task_id, revision, event_type, sanitized_payload)
  values (task.id, task.revision, 'task.cancelled', jsonb_build_object('idempotencyKey', p_idempotency_key));
  return jsonb_build_object('id', task.id, 'status', task.status, 'revision', task.revision);
end;
$function$

